// darkness at edges
let gr=ctx.createLinearGradient(0,0,0,H);gr.addColorStop(0,'#07091122');gr.addColorStop(.72,'#07091100');gr.addColorStop(1,'#08090d55');ctx.fillStyle=gr;ctx.fillRect(0,0,W,H);}
const $=id=>document.getElementById(id),keys=new Set();
const interactables=[
 {x:76,label:'[ E ] ENTRAR A CASA',type:'home'},
 {x:255,label:'[ E ] ABRIR TIENDA',type:'shop'},
 {x:423,label:'[ E ] HOSPITAL',type:'hospital'},
 {x:702,label:'[ E ] SEGURIDAD PÚBLICA',type:'office'},
 {x:1058,label:'[ E ] ESTACIÓN',type:'station'}
];
function notify(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');toastTimer=145}
function updateHUD(){
 $('hudName').textContent=player.name.toUpperCase();$('level').textContent=player.level;
 $('money').textContent=Math.floor(player.money).toLocaleString('es-ES');$('hpText').textContent=`${Math.ceil(player.hp)} / 100`;$('stText').textContent=`${Math.ceil(player.energy)} / 70`;
 $('hpBar').style.width=`${clamp(player.hp,0,100)}%`;$('stBar').style.width=`${clamp(player.energy/70*100,0,100)}%`;
 if(quest===0){$('questTitle').textContent='Un favor rápido';$('questDesc').textContent='Habla con el encargado frente a la tienda. A cualquiera le viene bien un poco de dinero.';$('questStatus').textContent='OBJETIVO: LOCALIZAR';$('objective').innerHTML='OBJETIVO &nbsp; <b>Encuentra un trabajo y paga tu deuda</b>'}
 if(quest===1){$('questTitle').textContent='Ruidos en el callejón';$('questDesc').textContent='Algo se mueve cerca del paso elevado. Encárgate del demonio y vuelve por tu paga.';$('questStatus').textContent=`OBJETIVO: ELIMINAR ${enemy.alive?'1':'0'} DEMONIO`;$('objective').innerHTML='OBJETIVO &nbsp; <b>Elimina al demonio del callejón →</b>'}
 if(quest===2){$('questTitle').textContent='Trabajo terminado';$('questDesc').textContent='El vecindario está más tranquilo. Vuelve con el encargado para cobrar la recompensa.';$('questStatus').textContent='OBJETIVO: COBRAR';$('objective').innerHTML='OBJETIVO &nbsp; <b>Vuelve a la tienda y cobra</b>'}
 if(quest>=3){$('questTitle').textContent='Deuda pendiente';$('questDesc').textContent=`Deuda: ¥ ${player.debt.toLocaleString('es-ES')}. Paga en Seguridad Pública o sigue explorando.`;$('questStatus').textContent=player.debt?'OBJETIVO: REDUCIR DEUDA':'CONTRATO CUMPLIDO';$('objective').innerHTML=player.debt?'OBJETIVO &nbsp; <b>Visita Seguridad Pública para pagar</b>':'OBJETIVO &nbsp; <b>Has saldado tu deuda. La noche es tuya.</b>'}
 let zone=player.x<180?'DISTRITO RESIDENCIAL':player.x<550?'CALLE COMERCIAL':player.x<830?'SEGURIDAD PÚBLICA':player.x<1100?'DISTRITO CENTRAL':player.x<1370?'ESTACIÓN DE TOKYO':'ZONA INDUSTRIAL';$('locationName').textContent=zone;
}
function gainXP(n){player.xp+=n;if(player.xp>=player.level*100){player.xp-=player.level*100;player.level++;player.hp=100;player.energy=70;notify(`¡NIVEL ${player.level}! Salud y energía restauradas.`)}}
function save(){try{localStorage.setItem('devilContractsSave',JSON.stringify({name:player.name,skin:player.skin,money:player.money,debt:player.debt,hp:player.hp,energy:player.energy,xp:player.xp,level:player.level,x:player.x,quest,kills,started:true}))}catch(e){}}
function load(){try{const d=JSON.parse(localStorage.getItem('devilContractsSave')||'null');if(d){Object.assign(player,{name:d.name||'Aki',skin:d.skin||0,money:d.money??1200,debt:d.debt??5000,hp:d.hp??100,energy:d.energy??70,xp:d.xp??0,level:d.level??1,x:d.x??105});quest=d.quest||0;kills=d.kills||0;if(quest>0)enemy.alive=!(quest>=2||kills>0);if(quest===1&&kills===0)enemy.alive=true;return true}}catch(e){}return false}
function interact(){if(!started)return;let target=null;
 if(Math.abs(player.x-npc.x)<42)target={type:'npc'};
 // agent is the debt payment point
 if(Math.abs(player.x-1190)<36)target={type:'agent'};
 for(const item of interactables){if(Math.abs(player.x-item.x)<30&&(!target||item.type==='office'))target=item}
 if(!target){notify('No hay nada con qué interactuar.');return}
 switch(target.type){
  case'npc':
   if(quest===0){quest=1;player.money+=800;gainXP(25);enemy.alive=true;enemy.hp=enemy.max;notify('TRABAJO ACEPTADO · +¥800 · Ruidos en el callejón')}
   else if(quest===2){quest=3;player.money+=1400;gainXP(80);notify('TRABAJO COMPLETADO · +¥1.400 · ¡Buen trabajo!')}
   else if(quest===1)notify('ENCARGADO: «El callejón. No dejes que llegue a la avenida.»');else notify('ENCARGADO: «La ciudad no va a limpiarse sola.»');break;
  case'agent':case'office':
   if(player.debt<=0){notify('DEUDA SALDADA. Por fin puedes respirar.');break}
   if(player.money<=0){notify('No tienes dinero. Busca trabajo antes de volver.');break}
   {let pay=Math.min(player.money,500,player.debt);player.money-=pay;player.debt-=pay;gainXP(10);notify(`PAGO RECIBIDO · −¥${pay} de deuda · Restan ¥${player.debt}`);if(quest<3)quest=3}break;
  case'home':player.hp=100;player.energy=70;player.money=Math.max(0,player.money-30);notify('Descansaste. Salud y energía restauradas · alquiler −¥30');break;
  case'shop':if(player.money>=100){player.money-=100;player.hp=Math.min(100,player.hp+35);player.energy=Math.min(70,player.energy+25);notify('Compraste un onigiri · +SALUD +ENERGÍA · −¥100')}else notify('No te alcanza para un onigiri (¥100).');break;
  case'hospital':if(player.money>=250){player.money-=250;player.hp=100;notify('Atención médica · salud restaurada · −¥250')}else notify('La consulta cuesta ¥250.');break;
  case'station':notify('El último tren ya pasó. Quizá sea mejor caminar.');break;
 }
 updateHUD();save();
}
function attack(){if(!started||player.attack>0)return;player.attack=12;player.energy=Math.max(0,player.energy-3);
 if(enemy.alive&&Math.abs(enemy.x-player.x)<57&&(enemy.x-player.x)*player.face>-8){enemy.hp--;enemy.hit=5;enemy.phase=0;if(enemy.hp<=0){enemy.alive=false;kills++;player.money+=300;gainXP(55);notify('DEMONIO ELIMINADO · +¥300 · +55 XP');if(quest===1)quest=2;updateHUD();save()}else notify('¡IMPACTO! El demonio retrocede.')}
}
function contract(){if(!started)return;if(player.energy<28){notify('ENERGÍA INSUFICIENTE · Descansa o espera.');return}if(!enemy.alive||Math.abs(enemy.x-player.x)>115){notify('No hay demonios cerca para invocar el pacto.');return}player.energy-=28;contractFx=22;enemy.hp-=2;enemy.hit=8;notify('PACTO DE SANGRE · El zorro responde.');if(enemy.hp<=0){enemy.alive=false;kills++;player.money+=300;gainXP(55);notify('¡DEVORADO! · +¥300 · +55 XP');if(quest===1)quest=2}updateHUD();save()}
let jumpRequest=false;
function step(){requestAnimationFrame(step);frame++;
 if(started){let left=keys.has('a')||keys.has('arrowleft')||keys.has('left'),right=keys.has('d')||keys.has('arrowright')||keys.has('right');let speed=keys.has('shift')?2.45:1.55;player.vx=(right?speed:0)-(left?speed:0);if(player.vx)player.face=player.vx>0?1:-1;player.x=clamp(player.x+player.vx,15,WORLD-20);if(jumpRequest&&player.y>=GROUND-player.h-1){player.vy=-5.4;player.energy=Math.max(0,player.energy-1)}jumpRequest=false;player.vy+=.27;player.y+=player.vy;if(player.y>GROUND-player.h){player.y=GROUND-player.h;player.vy=0}if(player.attack>0)player.attack--;if(player.invuln>0)player.invuln--;if(contractFx>0)contractFx--;if(enemy.hit>0)enemy.hit--;
  // Demon stalks the player and strikes at close range
  if(enemy.alive){enemy.phase++;let dx=player.x-enemy.x;if(Math.abs(dx)<205&&Math.abs(dx)>31)enemy.x+=Math.sign(dx)*.34;if(Math.abs(dx)<36&&enemy.phase%75===0&&player.invuln===0){player.hp=Math.max(0,player.hp-13);player.invuln=35;player.energy=Math.max(0,player.energy-7);notify('¡EL DEMONIO TE ALCANZÓ! Busca un refugio.');if(player.hp<=0){player.hp=60;player.x=105;player.money=Math.max(0,player.money-100);player.invuln=90;notify('DESMAYO · Despertaste en casa · −¥100')}}}
  player.energy=Math.min(70,player.energy+.045);camera=clamp(player.x-W*.43,0,WORLD-W);let closest=Math.abs(player.x-npc.x)<42?npc:null;near=closest;let hint=closest?(quest===0?'[ E ] HABLAR · ENCARGADO':'[ E ] HABLAR · ENCARGADO'):null;let obj=null;if(!closest){let d=999;for(const it of interactables){let dist=Math.abs(player.x-it.x);if(dist<30&&dist<d){d=dist;obj=it}}if(Math.abs(player.x-1190)<36){obj={label:'[ E ] HABLAR · PAGAR DEUDA',type:'agent'}}}
  near=closest;const interaction=$('interaction');if(hint||obj){interaction.textContent=hint||obj.label;interaction.classList.add('show')}else interaction.classList.remove('show');if(toastTimer>0){toastTimer--;if(!toastTimer)$('toast').classList.remove('show')}
  if(frame%30===0)updateHUD();if(frame%180===0)save();
 }
 render();
}
function doJump(){jumpRequest=true}
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' ','arrowdown'].includes(k))e.preventDefault();if(k==='e'||k==='enter'){if(!e.repeat)interact()}else if(k==='j'||k==='k'){if(!e.repeat)attack()}else if(k==='q'){if(!e.repeat)contract()}else if(k===' '||k==='w'||k==='arrowup'){if(!e.repeat)doJump()}else if(k==='shift')keys.add('shift');keys.add(k)});
window.addEventListener('keyup',e=>{let k=e.key.toLowerCase();keys.delete(k);if(k==='shift')keys.delete('shift')});
document.querySelectorAll('.touch-btn').forEach(btn=>{const key=btn.dataset.key;const on=e=>{e.preventDefault();keys.add(key);btn.classList.add('down')},off=e=>{e.preventDefault();keys.delete(key);btn.classList.remove('down')};btn.addEventListener('pointerdown',on);['pointerup','pointercancel','pointerleave'].forEach(ev=>btn.addEventListener(ev,off))});
document.querySelectorAll('.action-btn').forEach(btn=>{btn.addEventListener('pointerdown',e=>{e.preventDefault();if(btn.dataset.action==='attack')attack();if(btn.dataset.action==='interact')interact();if(btn.dataset.action==='contract')contract()})});
document.querySelectorAll('.option').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.option').forEach(o=>o.classList.remove('selected'));btn.classList.add('selected');player.skin=Number(btn.dataset.skin)}));
$('startBtn').addEventListener('click',()=>{player.name=$('playerInput').value.trim().slice(0,14)||'Aki';player.skin=Number(document.querySelector('.option.selected').dataset.skin);started=true;$('intro').classList.add('hidden');notify('TURNO INICIADO · El encargado te espera frente a la tienda.');updateHUD();save()});
$('resetBtn').addEventListener('click',()=>{if(confirm('¿Borrar la partida y empezar de nuevo?')){localStorage.removeItem('devilContractsSave');location.reload()}});
if(load()){ $('playerInput').value=player.name;document.querySelectorAll('.option').forEach(o=>o.classList.toggle('selected',Number(o.dataset.skin)===player.skin));updateHUD();if(quest>0){enemy.alive=quest===1&&kills===0;enemy.hp=enemy.max}}
step();
})();
</script></body></html>

